/**
 * Marker carried by user messages that were generated by a fired Canopy
 * watcher rather than typed by the user. `kind` is a short human-readable
 * description of the watcher that fired (e.g. `Pipeline completion (Deploy)`)
 * and is rendered as a "<kind> watcher has fired" title line above the
 * message content.
 */
export interface ChatWatcherFiredInfo {
  kind: string;
  /**
   * Original watcher messages folded into this turn when several watcher
   * deliveries accumulated adjacently in the host queue. The combined
   * `kind` is the aggregate title shown on the bubble; these entries power
   * the detail tooltip without exposing provider-only event payloads.
   */
  combinedWatchers?: Array<{
    kind: string;
    text: string;
  }>;
}

/** Display-only attribution for a user message accepted from another agent. */
export interface ChatAgentSentInfo {
  sender:
    | {
        kind: 'project';
        projectType: 'code' | 'cowork';
        projectId: string;
        taskId: string;
        chatId: string;
      }
    | {
        kind: 'bot';
        botId: string;
        taskId: string;
        chatId: string;
      };
  /** Sender chat title captured when the message was accepted. */
  chatTitle: string;
  /** Sender project name captured when the message was accepted. */
  projectLabel: string;
}

/** Serializable delivery facts. Admission is not model receipt or execution. */
export interface ChatSteeringCapabilities {
  provider: 'claude' | 'codex';
  generation: string;
  steer: boolean;
  withdraw: boolean;
  interrupt: boolean;
}

export type ChatInputAdmission =
  | { kind: 'accepted'; attemptId: string; providerTurnId?: string }
  | {
      kind: 'rejected' | 'unknown';
      attemptId: string;
      reason: string;
      /** The provider proved that no input was accepted, so ordinary dispatch is safe. */
      fallback?: 'ordinary';
    };

export type ChatInputWithdrawal =
  | { kind: 'withdrawn'; attemptId: string; evidenceId: string }
  | { kind: 'picked-up' | 'unsupported'; attemptId: string }
  | { kind: 'unconfirmed'; attemptId: string; reason: string };

export interface ChatInputDeliveryEvent {
  type: 'canopy_input_delivery';
  provider: 'claude' | 'codex';
  generation: string;
  attemptId: string;
  phase: 'accepted' | 'picked-up' | 'withdrawn' | 'completed' | 'unknown';
  providerTurnId?: string;
  itemId?: string;
  /** True only when this pickup opens a new root execution window. */
  startsTurn?: boolean;
  userMessageId?: string;
  /** Host arbitration result for a pickup that attempted to start a turn. */
  turnRootAccepted?: boolean;
}

export type ChatInputDeliveryState =
  | 'sending'
  | 'pending'
  | 'cancelling'
  | 'editing'
  | 'cancelled'
  | 'picked-up'
  | 'uncertain'
  | 'queued';

export interface ChatInputAttempt<Payload = unknown> {
  id: string;
  generation: string;
  provider: 'claude' | 'codex';
  createdAt: number;
  /** Exact host submission for local audit/recovery; never included in UI views. */
  submittedText?: string;
  /** User-visible text captured for this attempt before later edits replace the row payload. */
  displayText?: string;
  /** Immutable structured request captured for attempt-specific recovery and projection. */
  payloadSnapshot?: Payload;
  admittedAt?: number;
  pickedUpAt?: number;
  withdrawnAt?: number;
  completedAt?: number;
  uncertainAt?: number;
  providerTurnId?: string;
  itemId?: string;
  rootUserMessageId?: string;
  turnOutcome?: 'completed' | 'failed' | 'cancelled' | 'interrupted';
  turnSettledAt?: number;
}

/** Payload is host-owned; browser projections expose only presentation fields. */
export interface ChatInputDeliveryRow<Payload = { text: string }> {
  id: string;
  revision: number;
  createdAt: number;
  state: ChatInputDeliveryState;
  text: string;
  payload: Payload;
  settingsKey: string;
  origin?: 'desktop' | 'portal';
  attempts: ChatInputAttempt<Payload>[];
  currentAttemptId?: string;
  draft?: string;
  editResubmits?: boolean;
  queueIntent?: { commandId: string; epoch?: number };
  reason?: string;
  /** User hid this delivery notice; attempt evidence and deduplication remain authoritative. */
  dismissedAt?: number;
}

export interface ChatInputDeliveryLedger<Payload = { text: string }> {
  version: 1;
  epoch: number;
  rows: ChatInputDeliveryRow<Payload>[];
}

export type ChatInputDeliveryAction =
  | 'dismiss'
  | 'cancel'
  | 'queue'
  | 'edit'
  | 'save-draft'
  | 'save'
  | 'resend'
  | 'resend-original'
  | 'close-editor';

export interface ChatInputDeliveryView {
  id: string;
  revision: number;
  state: ChatInputDeliveryState;
  text: string;
  draft?: string;
  editResubmits?: boolean;
  reason?: string;
  /** Public watcher attribution retained across delivery-state transitions. */
  watcherFired?: ChatWatcherFiredInfo;
  /** Public agent-sender attribution retained across delivery-state transitions. */
  agentSent?: ChatAgentSentInfo;
  attachmentCount: number;
  canWithdraw: boolean;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isNonBlankString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

/** Copy only public attribution; malformed metadata must not discard the input. */
export function parseChatWatcherFiredInfo(
  value: unknown,
): ChatWatcherFiredInfo | undefined {
  if (!isRecord(value) || typeof value.kind !== 'string') return undefined;
  if (value.combinedWatchers === undefined) return { kind: value.kind };
  if (!Array.isArray(value.combinedWatchers)) return undefined;
  const combinedWatchers: NonNullable<
    ChatWatcherFiredInfo['combinedWatchers']
  > = [];
  for (const watcher of value.combinedWatchers) {
    if (
      !isRecord(watcher) ||
      typeof watcher.kind !== 'string' ||
      typeof watcher.text !== 'string'
    )
      return undefined;
    combinedWatchers.push({ kind: watcher.kind, text: watcher.text });
  }
  return { kind: value.kind, combinedWatchers };
}

/**
 * Copy only the public agent-sender attribution. Unknown display metadata is
 * ignored; malformed or mixed project/bot variants are rejected.
 */
export function parseChatAgentSentInfo(
  value: unknown,
): ChatAgentSentInfo | undefined {
  if (
    !isRecord(value) ||
    !isRecord(value.sender) ||
    typeof value.chatTitle !== 'string' ||
    typeof value.projectLabel !== 'string'
  )
    return undefined;

  const sender = value.sender;
  if (sender.kind === 'project') {
    if (
      'botId' in sender ||
      (sender.projectType !== 'code' && sender.projectType !== 'cowork') ||
      !isNonBlankString(sender.projectId) ||
      !isNonBlankString(sender.taskId) ||
      !isNonBlankString(sender.chatId)
    )
      return undefined;
    return {
      sender: {
        kind: 'project',
        projectType: sender.projectType,
        projectId: sender.projectId,
        taskId: sender.taskId,
        chatId: sender.chatId,
      },
      chatTitle: value.chatTitle,
      projectLabel: value.projectLabel,
    };
  }

  if (sender.kind === 'bot') {
    if (
      'projectId' in sender ||
      'projectType' in sender ||
      !isNonBlankString(sender.botId) ||
      !isNonBlankString(sender.taskId) ||
      !isNonBlankString(sender.chatId)
    )
      return undefined;
    return {
      sender: {
        kind: 'bot',
        botId: sender.botId,
        taskId: sender.taskId,
        chatId: sender.chatId,
      },
      chatTitle: value.chatTitle,
      projectLabel: value.projectLabel,
    };
  }

  return undefined;
}

function isChatInputDeliveryState(
  value: unknown,
): value is ChatInputDeliveryState {
  switch (value) {
    case 'sending':
    case 'pending':
    case 'cancelling':
    case 'editing':
    case 'cancelled':
    case 'picked-up':
    case 'uncertain':
    case 'queued':
      return true;
    default:
      return false;
  }
}

export function parseInputDeliveryViews(
  value: unknown,
): ChatInputDeliveryView[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter((candidate: unknown): candidate is ChatInputDeliveryView => {
      if (!isRecord(candidate)) return false;
      const row = candidate;
      return (
        typeof row.id === 'string' &&
        typeof row.text === 'string' &&
        typeof row.revision === 'number' &&
        Number.isSafeInteger(row.revision) &&
        row.revision > 0 &&
        isChatInputDeliveryState(row.state) &&
        typeof row.attachmentCount === 'number' &&
        Number.isSafeInteger(row.attachmentCount) &&
        row.attachmentCount >= 0 &&
        typeof row.canWithdraw === 'boolean' &&
        (row.draft === undefined || typeof row.draft === 'string') &&
        (row.reason === undefined || typeof row.reason === 'string') &&
        (row.editResubmits === undefined ||
          typeof row.editResubmits === 'boolean')
      );
    })
    .map((row) => {
      const agentSent = parseChatAgentSentInfo(row.agentSent);
      return {
        id: row.id,
        revision: row.revision,
        state: row.state,
        text: row.text,
        attachmentCount: row.attachmentCount,
        canWithdraw: row.canWithdraw,
        watcherFired: parseChatWatcherFiredInfo(row.watcherFired),
        ...(agentSent !== undefined ? { agentSent } : {}),
        ...(row.draft !== undefined ? { draft: row.draft } : {}),
        ...(row.reason !== undefined ? { reason: row.reason } : {}),
        ...(row.editResubmits !== undefined
          ? { editResubmits: row.editResubmits }
          : {}),
      };
    });
}

export function parseSteeringCapabilities(
  value: unknown,
): ChatSteeringCapabilities | undefined {
  if (!isRecord(value)) return undefined;
  const data = value;
  if (
    (data.provider !== 'claude' && data.provider !== 'codex') ||
    typeof data.generation !== 'string' ||
    typeof data.steer !== 'boolean' ||
    typeof data.withdraw !== 'boolean' ||
    typeof data.interrupt !== 'boolean'
  )
    return undefined;
  return {
    provider: data.provider,
    generation: data.generation,
    steer: data.steer,
    withdraw: data.withdraw,
    interrupt: data.interrupt,
  };
}
